css:
@keyframes bannerSlide { 
  0% { background-position: 0% 0px; }
  100% { background-position: 200% 0px; }
}

@keyframes walkerStep { 
  0%, 100% { transform: translate(-50%, -58%) scaleX(-1) rotate(8deg); }
  50% { transform: translate(-50%, -42%) scaleX(-1) rotate(-8deg); }
}

@keyframes walkerFinish { 
  0% { transform: translate(-50%, -50%) scaleX(-1) scale(0.85); }
  45% { transform: translate(-50%, -78%) scaleX(-1) scale(1.5) rotate(14deg); }
  70% { transform: translate(-50%, -58%) scaleX(-1) scale(1.15) rotate(-8deg); }
  100% { transform: translate(-50%, -50%) scaleX(-1) scale(1); }
}

@keyframes arrowLiftUp { 
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-12px); }
}

@keyframes arrowLiftDown { 
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(12px); }
}

@keyframes arrowTurnLeft { 
  0%, 100% { transform: translateX(0px) rotate(0deg); }
  50% { transform: translateX(-10px) rotate(-18deg); }
}

@keyframes arrowTurnRight { 
  0%, 100% { transform: translateX(0px) rotate(0deg); }
  50% { transform: translateX(10px) rotate(18deg); }
}

@keyframes arrowMarch { 
  0% { transform: translateY(10px); opacity: 0.35; }
  50% { transform: translateY(-4px); opacity: 1; }
  100% { transform: translateY(-16px); opacity: 0; }
}

@keyframes arrowArrive { 
  0% { transform: scale(0.4); opacity: 0; }
  60% { transform: scale(1.18); opacity: 1; }
  100% { transform: scale(1); }
}

@keyframes arriveIconPop { 
  0% { transform: scale(0.4); opacity: 0; }
  60% { transform: scale(1.12); opacity: 1; }
  100% { transform: scale(1); }
}

@keyframes arriveRingPulse { 
  0% { opacity: 0.5; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.4); }
}

@keyframes arriveCheckDraw { 
  100% { stroke-dashoffset: 0; }
}

@keyframes particlePop { 
  0% { transform: translate(-50%, -50%) scale(0.2); opacity: 1; }
  65% { opacity: 1; }
  100% { transform: translate(calc(-50% + var(--dx,0px)), calc(-50% + var(--dy,0px))) scale(1); opacity: 0; }
}

@keyframes particleRing { 
  0% { transform: translate(-50%, -50%) scale(0.2); opacity: 0.9; }
  100% { transform: translate(-50%, -50%) scale(2.6); opacity: 0; }
}

@media (max-width: 640px) {
  html, body { display: block; gap: 0px; height: 100%; overflow: hidden; text-size-adjust: 100%; overscroll-behavior: none; }
  .phone { width: 100%; height: 100%; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 0px; box-shadow: none; }
  .screen { top: 0px; padding-top: calc(16px + env(safe-area-inset-top)); padding-left: calc(16px + env(safe-area-inset-left)); padding-right: calc(16px + env(safe-area-inset-right)); padding-bottom: calc(16px + env(safe-area-inset-bottom)); }
  button, .btn, input { -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
}

@media (max-width: 360px) {
  .keypad button { font-size: 18px; }
  .big { padding: 15px; font-size: 16px; }
}

@keyframes qrScanMove { 
  0%, 100% { top: 23%; }
  50% { top: 77%; }
}

@keyframes aiPulse { 
  0%, 100% { opacity: 0.35; }
  50% { opacity: 1; }
}

@keyframes fxScanFlicker { 
  50% { opacity: 0.22; }
}
